import{_ as o,J as i,b as t,e as n,a8 as r,f as s,L as d}from"./chunks/framework.CumEd6mW.js";const b=JSON.parse('{"title":"GR32_Layers","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Layers","entity":"GR32_Layers","kind":"Unit","summary":"Provides classes, interfaces, and types for managing interactive 2D image and vector layers, mouse handling, and rubberband selection controls.","title":"GR32_Layers","date":1788857836000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Layers/index.md","filePath":"api/GR32_Layers/index.md","lastUpdated":1788857836000,"timestamp":1788857836000,"datetime":"2026-09-08T08:57:16.000Z"}'),c={name:"api/GR32_Layers/index.md"};function l(p,e,m,y,u,g){const a=i("ApiMembers");return t(),n("div",null,[e[0]||(e[0]=r('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32_Layers</code> unit implements the layer framework in Graphics32. It provides a comprehensive set of classes and tools for creating and managing visual layers rendered on top of visual controls or bitmaps.</p><p>Key capabilities provided by <code>GR32_Layers</code> include:</p><ul><li><strong>Layer Management</strong>: <code>TLayerCollection</code> manages ordered lists of layers, Z-ordering, visibility, mouse capture, coordinate transformation, and invalidation notifications.</li><li><strong>Base Layer Framework</strong>: <code>TCustomLayer</code> provides fundamental layer behaviors, visibility options (<code>LOB_*</code>), hit testing, mouse/keyboard event dispatching, and invalidation hooks.</li><li><strong>Positioned &amp; Bitmap Layers</strong>: <code>TPositionedLayer</code>, <code>TCustomIndirectBitmapLayer</code>, <code>TIndirectBitmapLayer</code>, <code>TCustomBitmapLayer</code>, and <code>TBitmapLayer</code> support moving, scaling, clipping, and rendering 32-bit bitmaps with optional alpha-channel hit testing.</li><li><strong>Rubberband Selection &amp; Manipulation</strong>: <code>TCustomRubberBandLayer</code>, <code>TPolygonRubberbandLayer</code>, and <code>TRubberbandLayer</code> provide design-time or interactive visual frames with draggable control vertices and sizing handles for interactive object transformation.</li><li><strong>Notification Interfaces</strong>: Standard interfaces (<code>ILayerNotification</code>, <code>IUpdateRectNotification</code>, <code>ILayerUpdateNotification</code>, <code>ILayerListNotification</code>, etc.) enable low-coupling event propagation and customization.</li></ul>',4)),s("p",null,[d(a,{type:"members"})])])}const f=o(c,[["render",l]]);export{b as __pageData,f as default};
